-- PATRIMONIAL PRO → banco da Gestão Empresarial e Financeiro (agenda-pro / vuwgxndahrzinfdlapxz)
-- Estrutura extraída em 18/10/2026 do banco antigo "patrimonial-pro" (rujfstmskkgyeksspyoa): 29 tabelas pat_*, regras,
-- vínculos (inclusive pat_usuarios.id e pat_superadmins.usuario_id → auth.users) e índices. Só acréscimos (nenhuma tabela
-- pat_* existia no destino). Diferença proposital: as tabelas não ficam abertas para quem não está logado (anon).
-- APLICADO em 18/10/2026 no agenda-pro como migration `patrimonial_001_estrutura` (este arquivo, com RLS ligado e revoke
-- anon no fim, para as tabelas nunca ficarem expostas entre um passo e outro); depois `patrimonial_002_funcoes_e_acesso`.
-- Conferido: impressão digital (colunas, regras, índices, funções, permissões das funções, políticas, gatilhos, RLS,
-- acessos sem anon, bucket) IGUAL à do banco antigo, fora as 2 diferenças propositais descritas no 002.
-- Dados (18/10/2026): copiados pelo SQL (sem passar por arquivo no repositório — há dados pessoais), com os gatilhos
-- desligados durante a cópia (session_replication_role = replica, para a cópia não gerar auditoria nova) e
-- pat_auditoria_id_seq ajustada para 15. Ids dos logins trocados pelos ids do banco da Agenda, pelo e-mail
-- (2 dos 3 já existiam lá). O 3º login foi criado com o mesmo id e senha aleatória (bloqueado até definirem a senha).
-- Conferência: md5 de cada uma das 15 tabelas com dados IGUAL ao da origem (já com os ids trocados); nenhum vínculo órfão.
-- Teste de acesso: Cleiver e Elieser veem a empresa e os dados; um login só da Agenda vê 0.

create sequence if not exists public.pat_auditoria_id_seq;
create table if not exists public.pat_anexos (id uuid default gen_random_uuid() not null, tenant_id uuid not null, ativo_id uuid, nome_arquivo text not null, storage_path text not null, mime_type text, tamanho bigint, created_at timestamp with time zone default now() not null, created_by uuid);
create table if not exists public.pat_ativo_eventos (id uuid default gen_random_uuid() not null, tenant_id uuid not null, ativo_id uuid not null, data_evento date not null, tipo text, descricao text, valor numeric(18,2), created_at timestamp with time zone default now() not null, created_by uuid);
create table if not exists public.pat_ativos (id uuid default gen_random_uuid() not null, tenant_id uuid not null, tipo_ativo text not null, descricao text not null, proprietario_id uuid, documento text, valor_aquisicao numeric(15,2), data_aquisicao date, valor_atual numeric(15,2), data_avaliacao date, situacao text default 'ativo'::text not null, detalhes jsonb default '{}'::jsonb not null, observacoes text, ativo boolean default true not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, created_by uuid default auth.uid(), integralizado_por_id uuid, valor_integralizacao numeric(15,2), data_integralizacao date, codigo_irpf text);
create table if not exists public.pat_ativos_financeiros (ativo_id uuid not null, instituicao text, tipo_aplicacao text, identificador text, quantidade numeric(18,6), valor_aplicado numeric(18,2), rentabilidade text, vencimento date);
create table if not exists public.pat_ativos_imoveis (ativo_id uuid not null, tipo_imovel text, matricula text, cartorio_cri text, inscricao_iptu text, endereco text, municipio text, uf text, area_terreno numeric(14,2), area_construida numeric(14,2), fracao_ideal numeric(9,6), valor_venal numeric(18,2), latitude numeric(10,7), longitude numeric(10,7), nirf_itr text, ccir text, car text, georref_incra text, area_reserva numeric(14,2));
create table if not exists public.pat_ativos_participacoes (ativo_id uuid not null, empresa_nome text, cnpj text, tipo_participacao text, classe text, quantidade numeric(18,4), percentual numeric(9,6), valor_nominal numeric(18,2), capital_social_total numeric(18,2), metodo_avaliacao text);
create table if not exists public.pat_ativos_veiculos (ativo_id uuid not null, categoria text, marca text, modelo text, ano_fabricacao integer, ano_modelo integer, placa_registro text, renavam_matricula text, chassi text, cor text);
create table if not exists public.pat_auditoria (id bigint default nextval('pat_auditoria_id_seq'::regclass) not null, tenant_id uuid, tabela text not null, operacao text not null, registro_id uuid, usuario_id uuid, dados_antes jsonb, dados_depois jsonb, contexto text, created_at timestamp with time zone default now() not null);
