create table if not exists public.pat_avaliacoes (id uuid default gen_random_uuid() not null, tenant_id uuid not null, ativo_id uuid not null, data_aval date not null, valor numeric(18,2), fonte text, responsavel text, created_at timestamp with time zone default now() not null, created_by uuid);
create table if not exists public.pat_doacoes (id uuid default gen_random_uuid() not null, tenant_id uuid not null, doador_id uuid not null, donatario_id uuid not null, objeto_tipo text default 'quota'::text not null, participacao_id uuid, ativo_id uuid, descricao text, percentual numeric(7,4), valor numeric(15,2), reserva_usufruto boolean default false not null, usufrutuario_id uuid, cl_inalienabilidade boolean default false not null, cl_impenhorabilidade boolean default false not null, cl_incomunicabilidade boolean default false not null, cl_reversao boolean default false not null, data_doacao date, uf character(2), itcmd_aliquota numeric(6,3), itcmd_valor numeric(15,2), observacoes text, ativo boolean default true not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, created_by uuid default auth.uid(), onus_gerado boolean default false not null, aplicada boolean default false not null, data_aplicacao date);
create table if not exists public.pat_documento_tipos (id uuid default gen_random_uuid() not null, tenant_id uuid not null, nome text not null, exige_vencimento boolean default false not null, antecedencia_dias integer default 30 not null, ativo boolean default true not null, created_at timestamp with time zone default now() not null);
create table if not exists public.pat_documentos (id uuid default gen_random_uuid() not null, tenant_id uuid not null, vinculo_tipo text default 'geral'::text not null, vinculo_id uuid, nome text not null, categoria text, storage_path text not null, mime text, tamanho bigint, observacoes text, ativo boolean default true not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, created_by uuid default auth.uid(), data_vencimento date, tipo_id uuid);
