create table if not exists public.pat_onus (id uuid default gen_random_uuid() not null, tenant_id uuid not null, ativo_id uuid not null, tipo text not null, favorecido_id uuid, favorecido_nome text, valor numeric(15,2), descricao text, registro text, cartorio text, data_constituicao date, data_vencimento date, data_baixa date, situacao text default 'ativo'::text not null, observacoes text, ativo boolean default true not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, created_by uuid default auth.uid());
