create table if not exists public.pat_participacoes (id uuid default gen_random_uuid() not null, tenant_id uuid not null, sociedade_id uuid not null, socio_id uuid not null, tipo_titulo text default 'quota'::text not null, classe text, quantidade numeric(18,4), percentual numeric(7,4), valor_nominal numeric(15,2), administrador boolean default false not null, data_entrada date, data_saida date, observacoes text, ativo boolean default true not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, created_by uuid default auth.uid());
