do $$ declare r record; begin
  for r in select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'pat\_%' loop
    execute format('alter table public.%I enable row level security', r.relname);
    execute format('revoke all on public.%I from anon', r.relname);
  end loop;
end $$;
revoke all on sequence public.pat_auditoria_id_seq from anon;
